import json, time, urllib.request, urllib.error, sys
BASE = "http://localhost:8080"
tok = None
log = []
def get_token():
    global tok
    while True:
        try:
            r = urllib.request.urlopen(urllib.request.Request(BASE+"/token", method="POST", data=b""))
            tok = json.load(r)["token"]; return
        except urllib.error.HTTPError as e:
            handle_err(e, "/token")
def handle_err(e, path):
    body = e.read().decode(errors="replace")
    log.append((path, e.code, dict(e.headers), body[:300]))
    if e.code == 429:
        ra = e.headers.get("Retry-After")
        try: w = float(ra)
        except: w = 2
        time.sleep(w + 0.1)
    elif e.code >= 500:
        time.sleep(0.5)
    return body
def get(path, allow404=False):
    global tok
    for attempt in range(200):
        if tok is None: get_token()
        req = urllib.request.Request(BASE+path, headers={"Authorization": "Bearer "+tok})
        try:
            r = urllib.request.urlopen(req, timeout=30)
            raw = r.read()
            try: return json.loads(raw)
            except Exception:
                log.append((path, "badjson", raw[:200])); time.sleep(0.5); continue
        except urllib.error.HTTPError as e:
            if e.code == 401 or e.code == 403:
                handle_err(e, path); tok = None; continue
            if e.code == 404 and allow404:
                handle_err(e, path); return None
            handle_err(e, path)
        except Exception as e:
            log.append((path, "exc", repr(e))); time.sleep(0.5)
    raise RuntimeError("gave up "+path)

pages = {}
path = "/orders?page=1"
while path:
    d = get(path)
    pages[d["page"]] = d
    print(path, d["page"], d["total_pages"], len(d["items"]), d["next"], file=sys.stderr)
    path = d["next"]
json.dump(pages, open("/tmp/recon/pages.json","w"))
cids = sorted({o["customer_id"] for p in pages.values() for o in p["items"]})
custs = {}
for c in cids:
    custs[c] = get("/customers/"+c, allow404=True)
json.dump(custs, open("/tmp/recon/custs.json","w"))
json.dump(log, open("/tmp/recon/log.json","w"), default=str)
print("errors:", len(log), file=sys.stderr)
EOF
cd /tmp/recon && python3 -I fetch.py 2>&1 | tail -50

